<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MIFECO Pipeline Command Center</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    /* === RESET & ROOT === */
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
    :root {
      --bg-primary: #0f172a;
      --bg-secondary: #1e293b;
      --bg-card: #1a2332;
      --border: #334155;
      --text-primary: #e2e8f0;
      --text-secondary: #94a3b8;
      --accent: #00ffcc;
      --accent-dim: rgba(0,255,204,0.12);
      --accent2: #667eea;
      --success: #22c55e;
      --warning: #f59e0b;
      --danger: #ef4444;
      --orange: #f97316;
      --info: #06b6d4;
      --purple: #8b5cf6;
      --sidebar-w: 220px;
      --shadow: 0 4px 24px rgba(0,0,0,0.3);
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      display: flex;
      min-height: 100vh;
    }
    a { color: var(--accent); text-decoration: none; }
    a:hover { opacity: 0.85; }

    /* === SIDEBAR === */
    .sidebar {
      position: fixed;
      top: 0; left: 0;
      width: var(--sidebar-w);
      height: 100vh;
      background: #0a0f1a;
      border-right: 1px solid var(--border);
      display: flex;
      flex-direction: column;
      z-index: 100;
      overflow-y: auto;
    }
    .sidebar-logo {
      padding: 24px 20px 20px;
      border-bottom: 1px solid var(--border);
    }
    .sidebar-logo h1 {
      font-size: 16px;
      font-weight: 800;
      letter-spacing: 0.5px;
      color: var(--accent);
    }
    .sidebar-logo span {
      font-size: 10px;
      color: var(--text-secondary);
      letter-spacing: 2px;
      text-transform: uppercase;
    }
    .sidebar-nav { flex: 1; padding: 16px 0; }
    .sidebar-nav a {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 10px 20px;
      color: var(--text-secondary);
      font-size: 13px;
      font-weight: 500;
      transition: all 0.2s;
      border-left: 3px solid transparent;
    }
    .sidebar-nav a:hover, .sidebar-nav a.active {
      color: var(--text-primary);
      background: rgba(0,255,204,0.05);
      border-left-color: var(--accent);
    }
    .sidebar-nav a .icon { font-size: 16px; width: 20px; text-align: center; }
    .sidebar-footer {
      padding: 16px 20px;
      border-top: 1px solid var(--border);
      font-size: 11px;
    }
    .sidebar-footer a { color: var(--text-secondary); font-size: 11px; display: block; padding: 4px 0; }
    .sidebar-footer a:hover { color: var(--accent); }

    /* === MAIN CONTENT === */
    .main {
      margin-left: var(--sidebar-w);
      flex: 1;
      min-height: 100vh;
    }
    .container { max-width: 1400px; margin: 0 auto; padding: 28px 32px 40px; }

    /* === HEADER / STATS === */
    .hero {
      margin-bottom: 32px;
      animation: fadeIn 0.6s ease;
    }
    .hero h1 {
      font-size: 28px;
      font-weight: 800;
      background: linear-gradient(135deg, var(--text-primary), var(--accent));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero p {
      color: var(--text-secondary);
      font-size: 14px;
      margin-top: 2px;
      letter-spacing: 0.3px;
    }
    .stat-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-top: 20px;
    }
    .stat-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 20px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .stat-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow);
    }
    .stat-card .stat-icon {
      width: 48px; height: 48px;
      border-radius: 12px;
      background: var(--accent-dim);
      display: flex; align-items: center; justify-content: center;
      font-size: 22px;
      flex-shrink: 0;
    }
    .stat-card .stat-number {
      font-size: 28px;
      font-weight: 700;
      color: var(--accent);
      animation: pulseStat 2s ease-in-out infinite;
    }
    .stat-card .stat-label {
      font-size: 12px;
      color: var(--text-secondary);
      margin-top: 2px;
    }

    /* === SECTION TITLES === */
    .section-title {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 20px;
      padding-bottom: 8px;
      border-bottom: 1px solid var(--border);
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }
    .section-title .email-badge {
      font-size: 11px;
      font-weight: 500;
      background: var(--accent-dim);
      color: var(--accent);
      padding: 3px 10px;
      border-radius: 20px;
      font-family: monospace;
      letter-spacing: -0.2px;
    }
    .section { margin-bottom: 48px; animation: fadeIn 0.5s ease; }

    /* === OVERVIEW CARDS === */
    .pipeline-cards {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }
    .pipeline-overview-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 24px;
      cursor: pointer;
      transition: transform 0.25s, box-shadow 0.25s;
    }
    .pipeline-overview-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 8px 32px rgba(0,255,204,0.1);
    }
    .pipeline-overview-card h3 {
      font-size: 16px;
      font-weight: 700;
      color: var(--accent);
      margin-bottom: 4px;
    }
    .pipeline-overview-card .pipeline-email {
      font-size: 11px;
      color: var(--text-secondary);
      font-family: monospace;
      margin-bottom: 16px;
    }
    .pipeline-overview-card .stat-line {
      display: flex;
      justify-content: space-between;
      font-size: 13px;
      margin-bottom: 8px;
    }
    .pipeline-overview-card .stat-line strong { color: var(--text-primary); }
    .pipeline-overview-card .stat-line span { color: var(--accent); font-weight: 600; }
    .stage-bar {
      display: flex;
      height: 8px;
      border-radius: 4px;
      overflow: hidden;
      margin: 8px 0 12px;
    }
    .stage-bar .seg { height: 100%; transition: width 0.6s ease; }
    .pipeline-overview-card .products {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-top: 8px;
    }
    .pipeline-overview-card .products .tag {
      font-size: 10px;
      padding: 2px 8px;
      border-radius: 4px;
      background: var(--bg-secondary);
      color: var(--text-secondary);
      border: 1px solid var(--border);
    }

    /* === TABLES === */
    .table-wrap {
      overflow-x: auto;
      border-radius: 10px;
      border: 1px solid var(--border);
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
    }
    thead { background: #0a0f1a; }
    th {
      padding: 12px 14px;
      text-align: left;
      font-weight: 600;
      color: var(--text-secondary);
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      border-bottom: 1px solid var(--border);
    }
    td {
      padding: 10px 14px;
      border-bottom: 1px solid var(--border);
    }
    tbody tr { background: var(--bg-card); transition: background 0.15s; }
    tbody tr:nth-child(even) { background: #1a2635; }
    tbody tr:hover { background: #1e2d42; }

    /* === BADGES === */
    .badge {
      display: inline-block;
      padding: 2px 10px;
      border-radius: 12px;
      font-size: 11px;
      font-weight: 600;
    }
    .badge-stage-1 { background: #64748b33; color: #64748b; }
    .badge-stage-2 { background: #3b82f633; color: #3b82f6; }
    .badge-stage-3 { background: #8b5cf633; color: #8b5cf6; }
    .badge-stage-4 { background: #06b6d433; color: #06b6d4; }
    .badge-stage-5 { background: #f59e0b33; color: #f59e0b; }
    .badge-stage-6 { background: #f9731633; color: #f97316; }
    .badge-stage-7 { background: #22c55e33; color: #22c55e; }
    .badge-stage-8 { background: #14b8a633; color: #14b8a6; }
    .badge-icp-high   { background: #22c55e22; color: #22c55e; }
    .badge-icp-mid    { background: #f59e0b22; color: #f59e0b; }
    .badge-icp-low    { background: #f9731622; color: #f97316; }
    .badge-status-new { background: #3b82f622; color: #3b82f6; }
    .badge-status-active { background: #22c55e22; color: #22c55e; }

    /* === PRODUCT / SERVICE TIER CARDS === */
    .tier-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
      margin-top: 16px;
    }
    .tier-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 18px;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .tier-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow);
    }
    .tier-card h4 { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
    .tier-card .price {
      font-size: 20px;
      font-weight: 700;
      color: var(--accent);
      margin-bottom: 6px;
    }
    .tier-card p { font-size: 12px; color: var(--text-secondary); }

    /* === ACTION BUTTONS === */
    .action-links {
      display: flex;
      gap: 10px;
      margin-top: 16px;
      flex-wrap: wrap;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 8px 18px;
      border-radius: 8px;
      font-size: 12px;
      font-weight: 600;
      border: none;
      cursor: pointer;
      transition: all 0.2s;
      text-decoration: none;
    }
    .btn-primary {
      background: var(--accent);
      color: #0f172a;
    }
    .btn-primary:hover { background: #00e6b8; }
    .btn-outline {
      background: transparent;
      color: var(--text-primary);
      border: 1px solid var(--border);
    }
    .btn-outline:hover { border-color: var(--accent); color: var(--accent); }

    /* === INTAKE / SEQUENCE GRID === */
    .card-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }
    .index-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      transition: transform 0.25s, box-shadow 0.25s;
    }
    .index-card:hover {
      transform: translateY(-3px);
      box-shadow: 0 8px 32px rgba(0,0,0,0.4);
    }
    .index-card .gradient-block {
      height: 80px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
    }
    .index-card .card-body {
      padding: 18px;
    }
    .index-card .card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
    .index-card .card-body .desc { font-size: 12px; color: var(--text-secondary); margin-bottom: 8px; }
    .index-card .card-body .meta { font-size: 11px; color: var(--text-secondary); font-family: monospace; }
    .index-card .card-body .btn { margin-top: 10px; }

    /* === BOOK LIST === */
    .book-list {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px;
      margin: 12px 0;
    }
    .book-item {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 10px 14px;
      font-size: 12px;
    }
    .book-item .b-title { font-weight: 600; }
    .book-item .b-price { color: var(--accent); font-weight: 600; }

    /* === BULK TIERS === */
    .bulk-tiers {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-top: 10px;
